tostr = lambda s:  ', '.join([str(x) for x in s]) if type(s) == list else str(s)
sort_dict = lambda d: dict(sorted(d.items(), key=lambda item:item[1], reverse=True))


def format(x):
    if type(x) == str:
        x = x.replace('\u00b0C','°C').replace('℃', '°C')
        if x.endswith('1.0'):
            x = x[:-3]
        return x
    if type(x) == list:
        if len(x) == 2 and type(x[0]) == str and type(x[1]) == str:
            return format(x[0] + ' ' + x[1])
        if len(x) == 0 or x[0] is None:
            return []
        return [format(p) for p in x]
    if type(x) == dict:
        return x
    
    # print('--------------------', x, type(x))
    return x.json()


class StrClass:
    def __init__(self, **kargs):
        self.__dict__.update(**kargs)

    def __str__(self):
        assert type(self) != list
        dic = {k:str(v) for k, v in self.__dict__.items()}
        return json.dumps(dic)
    
    def __hash__(self):
        return int(hashlib.md5(str(self).encode(encoding='UTF-8')).hexdigest(), 16)

    def json(self):
        dic = self.__dict__
        delete_items = []
        for k, v in dic.items():
            if type(v) in [str, list]:
                dic[k] = format(v)
            elif 'json' not in dir(v) or not v.json() or v.json() == ' ':
                delete_items.append(k)
            else:
                # print(k, v)
                dic[k] = format(v)
        # print(delete_items)
        delete_keys(dic, *delete_items)
        if 'composition' in dic:
            dic['composition'] = ','.join(set(dic['composition']))
        delete_keys(dic, 'solvent')
        delete_keys(dic, *[k for k, v in dic.items() if not v])
        return dic


def dic2class(dic, obj):
    # print(dic, obj, type(obj))
    assert obj is not None and obj != []
    # obj = cls(*[None] * (cls.__init__.__code__.co_argcount - 1))
    
    if type(dic) == list:
        # 排除特殊情况：
        # [None, None] <__main__.Value object at 0x7f1efbae49d0> <class '__main__.Value'>
        # [] [<__main__.OPrecursor object at 0x7fe97f7257c0>] <class 'list'>
        if len(dic) and dic[0] is None: 
            return obj      # 不进行修改
        assert type(obj) == list
        cls = type(obj[0])
        # 注意这里一定要创建新的对象！！！
        if cls != list:
            return [dic2class(x, cls()) for x in dic]
        else:
            return [dic2class(x, obj[0]) for x in dic]
    elif type(dic) == dict:
        for name in dic: 
            if hasattr(obj, name):
                value = dic[name]
                if type(value) in [dict, list]:
                    assert getattr(obj, name) != []
                    value = dic2class(value, getattr(obj, name))
                setattr(obj, name, value)
            else:
                print(obj.__dict__)
                print(f'undefined at tr: {name} of {type(obj)}')
                exit(0)
        return obj
    else:
        # literal 直接返回元素本身
        return dic


