def delete_keys(dic, *keys):
    for key in keys:
        if key in dic:
            del dic[key]


class SynthesisConditions:
    lis : List[SynthesisCondition] = []
    dic = {
        "S_precursor": defaultdict(int),
        "M_precursor": defaultdict(int),
        "O_precursor": defaultdict(int),
        "operation": defaultdict(int)
    }

    def __init__(self, path) -> None:
        import json
        with open(path, 'r') as f:
            data_str = f.read()
        data_json = json.loads(data_str.replace('yield', 'Yield').replace('property', 'Property')
                    .replace('Melting point', 'melting_point')
                    .replace('Decomposition temperature', 'decomposition_temperature')
                    .replace('Boiling point', 'boiling_point'))
        print('loading data...')
        for d in tqdm(data_json):
            # print(f'---------------------{i}----------------------')
            obj = dic2class(d, SynthesisCondition())
            # print(obj.Property)
            # exit(0)
            # if i > 1:
            #     break
            assert type(obj) == SynthesisCondition
            self.lis.append(obj)

    def __len__(self):
        return len(self.lis)

    def __getitem__(self, ix):
        return self.lis[ix]

    def generate(self):
        for m in self.lis:
            for k in ['M_precursor', "S_precursor", "O_precursor", "operation"]:
                for t in m.__dict__[k]:
                    self.dic[k][t.name] += 1

        for k in ['M_precursor', "S_precursor", "O_precursor", "operation"]:
            self.dic[k] = sort_dict(self.dic[k])

        print(self.dic)
        with open('data/precursor_info.json', 'w') as f:
            json.dump(self.dic, f, indent=2)

    def export(self):
        import pandas as pd
        precursor_df = pd.DataFrame(columns=['name', 'composition', 'mof'])
        mof_df = pd.DataFrame(columns=['name', 'paper', 'temperature', 'time', 'operation'])
        paper_df = pd.DataFrame(columns=['doi', 'journal', 'date', 'title', 'authors'])
        print('exporting data...')
        for m in tqdm(self.lis):
            for k in ['M_precursor', "S_precursor", "O_precursor"]:
                for precursor in m.__dict__[k]:
                    precursor_df.loc[len(precursor_df)] = [precursor.name, tostr(precursor.composition), m.name]
            mof_df.loc[len(mof_df)] = [m.name, m.doi, tostr(m.temperature), tostr(m.time), tostr(m.operation)]
            mm = m.metadata
            if mm.doi not in paper_df['doi']:
                paper_df.loc[len(paper_df)] = [mm.doi, mm.journal, mm.date, mm.title, tostr(mm.author_list)]
        precursor_df.to_csv('output/precursor.csv')
        mof_df.to_csv('output/mof.csv')
        paper_df.to_csv('output/paper.csv')



